        final Github github = new RtGithub(key);
        repos = github.repos();
        repo = repos.create(
            Json.createObjectBuilder().add(
                "name", RandomStringUtils.randomAlphanumeric(Tv.TEN)
            ).add("auto_init", true).build()
        );
    }

    /**
